import{_ as o,o as e,c as a,a5 as s}from"./chunks/framework.D47SInms.js";const g=JSON.parse('{"title":"사용자 PC 접속 불가","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/user-pc-connection.md","filePath":"ko/manual/troubleshooting/user-pc-connection.md","lastUpdated":1791600043000}'),n={name:"ko/manual/troubleshooting/user-pc-connection.md"};function r(i,t,l,c,d,h){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="사용자-pc-접속-불가" tabindex="-1">사용자 PC 접속 불가 <a class="header-anchor" href="#사용자-pc-접속-불가" aria-label="Permalink to &quot;사용자 PC 접속 불가&quot;">​</a></h1><p>사용자가 직접 작업할 수 있는 PC에 NoMachine으로 접속되지 않는 경우입니다. <strong>U-PC, AI PC 모두 같은 사용자 PC</strong>이며, 주소는 이름이 아니라 <strong>어디에 있는지</strong>로 정해집니다.</p><table tabindex="0"><thead><tr><th>위치</th><th>IP</th></tr></thead><tbody><tr><td>로봇 <strong>내부</strong></td><td><code>192.168.0.12</code></td></tr><tr><td>로봇 <strong>외부</strong></td><td><code>192.168.0.13</code></td></tr></tbody></table><p>사용자 PC는 옵션 사양이라 탑재되지 않은 로봇도 있습니다.</p><h2 id="first-checks" tabindex="-1">먼저 확인할 것 <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;먼저 확인할 것 {#first-checks}&quot;">​</a></h2><ul><li>사용자 PC가 <strong>로봇 내부에 있는지 외부에 있는지</strong> 확인하고 위 표의 주소로 접속합니다.</li><li>접속하려는 PC가 로봇과 <strong>같은 네트워크</strong>에 연결되어 있는지 확인합니다. 로봇의 Wi-Fi(<code>RBQ_</code>로 시작하는 이름)에 연결되어 있어야 합니다.</li><li>사용자 PC에 전원이 들어와 있는지 확인합니다.</li></ul><h2 id="check-ip" tabindex="-1">주소가 표와 다를 때 <a class="header-anchor" href="#check-ip" aria-label="Permalink to &quot;주소가 표와 다를 때 {#check-ip}&quot;">​</a></h2><p><strong>원인:</strong> 사용자 PC가 표와 다른 주소를 사용 중이면 접속되지 않습니다.</p><p><strong>해결:</strong></p><ol><li>사용자 PC에 <strong>모니터를 직접 연결</strong>해 현재 IP를 확인합니다.</li><li>표와 다른 주소를 사용 중이라면 <strong>위치에 맞는 주소로 고정</strong>해 사용합니다.</li><li>다시 NoMachine으로 접속합니다.</li></ol><p>로봇의 전체 IP 구성은 <a href="/RBQ/nightly/ko/manual/interface/network.html">네트워크 구성도</a>를 참고하세요.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>모션 PC(<code>192.168.0.10</code>)는 로봇 동작에 직접 관여하므로 <strong>사용자가 접속할 수 없습니다.</strong> 개발 작업은 사용자 PC에서 진행하세요.</p></div></div><h2 id="session-fails" tabindex="-1">네트워크는 연결되는데 화면이 열리지 않습니다 <a class="header-anchor" href="#session-fails" aria-label="Permalink to &quot;네트워크는 연결되는데 화면이 열리지 않습니다 {#session-fails}&quot;">​</a></h2><p><strong>원인:</strong> 사용자 PC에 NoMachine이 설치되어 있지 않거나, 서버가 실행되지 않은 상태입니다.</p><p><strong>해결:</strong> 설치와 접속 절차는 아래 문서를 따라 진행하세요.</p><p><strong>→ <a href="/RBQ/nightly/ko/software/release-note/how-to-connect-rbq-dev-pc.html">RBQ 개발 PC 연결 방법</a></strong></p><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>사용자 PC에 모니터를 연결해 확인한 IP와, 접속 시 나타나는 오류 메시지를 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/nightly/ko/manual/support/">기술지원 요청</a></strong></p>',19)])])}const u=o(n,[["render",r]]);export{g as __pageData,u as default};
